import{_ as e,o as t,c as r,a5 as s}from"./chunks/framework.QWVCgkrI.js";const m=JSON.parse('{"title":"MSAAを切り替えて輪郭と床模様を見比べる","description":"","frontmatter":{"title":"MSAAを切り替えて輪郭と床模様を見比べる","study":{"source":"新規執筆","section":"practice","format":"sample","status":"published","domain":"graphics","collection":"msaa-observation","order":1,"summary":"同じシーンを単一サンプルとMSAAで描き、ポリゴンの斜めの輪郭と、床の模様のちらつきを比べる。","aliases":["MSAAの実践","WebGL 2","アンチエイリアシング","カバレッジ","リゾルブ"],"verification":"KhronosのOpenGL ES 3.0.6・WebGL 2.0仕様に照合（2026-11-13）"}},"headers":[],"relativePath":"practice/graphics/msaa-observation.md","filePath":"practice/graphics/msaa-observation.md"}'),i={name:"practice/graphics/msaa-observation.md"};function o(l,a,h,n,d,p){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="msaaを切り替えて輪郭と床模様を見比べる" tabindex="-1">MSAAを切り替えて輪郭と床模様を見比べる <a class="header-anchor" href="#msaaを切り替えて輪郭と床模様を見比べる" aria-label="Permalink to &quot;MSAAを切り替えて輪郭と床模様を見比べる&quot;">​</a></h1><p>単色のポリゴンと、斜めから見た市松模様の床を描きます。MSAAのオン・オフで何が変わるか、輪郭と床の奥を順に観察します。<a href="/study/graphics/postprocess/antialiasing.html">アンチエイリアシングの記事</a>で、輪郭と模様が異なる理由を図解しています。</p><p><a href="/study/samples/graphics/msaa-observation/index.html" target="_self">MSAAの比較デモを開く</a></p><h2 id="ポリゴンの輪郭を見る" tabindex="-1">ポリゴンの輪郭を見る <a class="header-anchor" href="#ポリゴンの輪郭を見る" aria-label="Permalink to &quot;ポリゴンの輪郭を見る&quot;">​</a></h2><ol><li>カメラを止めた状態で、MSAAをオフにします。黄色い三角形の斜めの辺が、画素ごとにどんな階段を作るか見ます。</li><li>MSAAをオンにして、同じ辺を見ます。ポリゴン色と背景色の間に中間色の画素が加わります。</li><li>画面のサンプル数を確認します。オフは1サンプル、オンは環境が確保できたサンプル数を表示します。利用できない場合は理由が表示されます。</li></ol><p>描画解像度は両方とも同じです。画素の違いが見えるよう、描いた画像を拡大して表示しています。</p><h2 id="床模様のちらつきを見る" tabindex="-1">床模様のちらつきを見る <a class="header-anchor" href="#床模様のちらつきを見る" aria-label="Permalink to &quot;床模様のちらつきを見る&quot;">​</a></h2><p>「カメラを横に動かす」をオンにして、三角形の輪郭から離れた床の奥を見ます。MSAAをオンにしても、床の奥には模様の明滅が残ります。このデモは、床を両方ともポイントサンプリングで描きます。床の内側では同じポリゴンが画素を覆い、模様が変わる原因はテクスチャを読む位置にあります。</p><p>床の方を改善する設定は、<a href="/study/practice/graphics/texture-filtering-observation.html">斜めの床でフィルタリングを比べる実践</a>で試せます。そこでは床の奥を見たまま、ポイントからトライリニア（ミップマップ）へ切り替えられます。</p><h2 id="webgl-2で切り替えている処理" tabindex="-1">WebGL 2で切り替えている処理 <a class="header-anchor" href="#webgl-2で切り替えている処理" aria-label="Permalink to &quot;WebGL 2で切り替えている処理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>設定</th><th>シーンの描画先</th><th>表示までの処理</th></tr></thead><tbody><tr><td>MSAAオフ</td><td>単一サンプルのRGBA8</td><td>描いた画像を画面に表示する</td></tr><tr><td>MSAAオン</td><td>マルチサンプルのRGBA8レンダーバッファ</td><td>同じ大きさの単一サンプルRGBA8へリゾルブしてから表示する</td></tr></tbody></table><p>オンの経路は <code>renderbufferStorageMultisample</code> で描画先を用意し、<code>blitFramebuffer</code> でリゾルブします。輪郭の1画素が持っていた複数の色サンプルを、表示用の1色にまとめる段階です。既定の描画バッファには <code>antialias: false</code> を指定し、サンプル数の違いはオフスクリーンの描画先で作っています。<a href="https://registry.khronos.org/webgl/specs/latest/2.0/" target="_blank" rel="noreferrer">WebGL 2.0仕様</a> · <a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">OpenGL ES 3.0.6仕様の §4.3.3</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>カメラを止めてMSAAを切り替えると、黄色いポリゴンの輪郭の画素はどう変わりますか。</p><details class="details custom-block"><summary>解答</summary><p>複数のサンプルで輪郭の内側と外側が拾われ、リゾルブ後はポリゴン色と背景色の中間色になる画素が現れます。</p></details></li><li><p>床の奥の模様を落ち着かせたい場合は、どの設定を調べますか。</p><details class="details custom-block"><summary>解答</summary><p>テクスチャの縮小フィルターを調べます。ミップマップを使うと、画素が覆う広い範囲の模様を反映した色を読みやすくなります。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/graphics/postprocess/antialiasing.html">アンチエイリアシング</a>で、MSAAと他の方式の違いを整理する。</li><li><a href="/study/graphics/texture/texture-filtering-and-mipmaps.html">テクスチャのフィルタリングとミップマップ</a>で、遠くの床で1画素が覆う範囲を確認する。</li><li><a href="/study/learn/roadmap.html?node=gfx-postprocess#graphics">3DCG・描画ロードマップの「ポストプロセスとAA」</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://registry.khronos.org/webgl/specs/latest/2.0/" target="_blank" rel="noreferrer">Khronos — WebGL 2.0 Specification</a> · <a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">OpenGL ES 3.0.6 Specification</a></li></ul>',18)])])}const b=e(i,[["render",o]]);export{m as __pageData,b as default};
